import { useState, useCallback } from 'react';
import { JxCalendar, JxButton } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date | null) => void;
}

function startOfDay(date: Date): Date {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

function addDays(date: Date, days: number): Date {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

const QUICK_OPTIONS: { label: string; getDate: () => Date }[] = [
  { label: 'Сегодня', getDate: () => startOfDay(new Date()) },
  { label: 'Вчера', getDate: () => addDays(startOfDay(new Date()), -1) },
  { label: 'Неделя назад', getDate: () => addDays(startOfDay(new Date()), -7) },
];

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [date, setDate] = useState<Date | null>(() => startOfDay(new Date()));

  const handleChange = useCallback(
    (value: Date | null) => {
      setDate(value);
      onChange?.(value);
    },
    [onChange]
  );

  const isActiveQuickOption = (optionDate: Date) =>
    date != null && startOfDay(date).getTime() === optionDate.getTime();

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-3, 12px)',
        alignItems: 'flex-start',
      }}
    >
      <div style={{ display: 'flex', gap: 'var(--jx-space-2, 8px)', flexWrap: 'wrap' }}>
        {QUICK_OPTIONS.map((option) => {
          const optionDate = option.getDate();
          return (
            <JxButton
              key={option.label}
              type="button"
              size="sm"
              variant={isActiveQuickOption(optionDate) ? 'primary' : 'outline'}
              onClick={() => handleChange(optionDate)}
            >
              {option.label}
            </JxButton>
          );
        })}
      </div>
      <JxCalendar locale="ru-RU" value={date} onValueChange={handleChange} />
    </div>
  );
}

